  package    org . assertj . assertions . generator ;   import static    java . lang . Thread . currentThread ;  import static      org . apache . commons . io . IOUtils . closeQuietly ;  import static      org . apache . commons . io . IOUtils . copy ;  import   java . io . File ;  import   java . io . IOException ;  import   java . io . InputStream ;  import   java . io . StringWriter ;  import   java . net . URL ;  import   java . net . URLDecoder ;  import     org . apache . commons . lang3 . CharEncoding ;   public class Template  {   private String  content ;   private final Type  type ;   public Template  (  Type type ,  String templateContent )  {    this . content = templateContent ;    this . type = type ; }   public Template  (  Type type ,  URL url )  {    this . type = type ;  try  {  File  urlFile =  new File  (  URLDecoder . decode  (  url . getFile  ( ) ,  CharEncoding . UTF_8 ) ) ;  if  (  !  urlFile . isFile  ( ) )  {  throw  new RuntimeException  (  "Failed to read template from an URL which is not a file, URL was :" + url ) ; }   content =  readContentThenClose  (  url . openStream  ( ) ) ; }  catch (   IOException e )  {  throw  new RuntimeException  (  "Failed to read template from " + url , e ) ; } }   public Template  (  Type type ,  File file )  {    this . type = type ;  String  path =  file . getPath  ( ) ;  try  {    this . content =  readTemplateFile  ( file ,  file . getPath  ( ) ) ; }  catch (   RuntimeException e )  {    this . content =  readTemplateFile  ( file ,  path . replace  ( '\\' , '/' ) ) ; } }   private String readTemplateFile  (  File file ,  String path )  {  try  {  InputStream  inputStream =    currentThread  ( ) . getContextClassLoader  ( ) . getResourceAsStream  ( path ) ;  return  readContentThenClose  ( inputStream ) ; }  catch (   Exception e )  {  throw  new RuntimeException  (  "Failed to read template from file " + file , e ) ; } }   public String getContent  ( )  {  return content ; }   public Type getType  ( )  {  return type ; }   private String readContentThenClose  (  InputStream input )  throws IOException  {  StringWriter  writer = null ;  try  {   writer =  new StringWriter  ( ) ;   copy  ( input , writer ) ;  return  writer . toString  ( ) ; }  finally  {   closeQuietly  ( input ) ;   closeQuietly  ( writer ) ; } }   public enum Type  {  IS ,  HAS_FOR_ARRAY ,  HAS_FOR_ITERABLE ,  HAS ,  HAS_FOR_PRIMITIVE ,  ASSERT_CLASS ,  HIERARCHICAL_ASSERT_CLASS ,  ABSTRACT_ASSERT_CLASS ,  ASSERTIONS_ENTRY_POINT_CLASS ,  ASSERTION_ENTRY_POINT ,  SOFT_ASSERTIONS_ENTRY_POINT_CLASS ,  SOFT_ENTRY_POINT_METHOD_ASSERTION ,  BDD_ASSERTIONS_ENTRY_POINT_CLASS ,  BDD_ENTRY_POINT_METHOD_ASSERTION ,  HAS_FOR_REAL_NUMBER  ; } }